const C=window.KerekCore,API=window.KerekAPI,SEED=window.KEREK_SEED;
const $=(s,r=document)=>r.querySelector(s),e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='kerek_v3';let storageWarning=false;
function load(key,fallback){try{const s=localStorage.getItem(key);return s?JSON.parse(s):C.clone(fallback);}catch(_){storageWarning=true;return C.clone(fallback);}}
const defaults={version:3,cart:{},favorites:[],seen:[],pantry:[],orders:[],tickets:[],name:'',phone:'',addresses:[],language:'ru',theme:'light',notifications:true,promo:'',bonus:0,balance:0,ledger:[],localProfile:false};
let S={...C.clone(defaults),...load(KEY,{})},D=C.clone(SEED),user=null,savingTimer=null,toastTimer=null,undo=null,orderKey=null;
let V={view:'home',query:'',category:'all',subcategory:'all',brand:'all',sort:'popular',sale:false,available:false,min:0,max:100000,profile:'account',selectedProduct:null,recipePeople:2,recipeMeal:'all',recipeMinutes:60,recipeVeg:false,recipeBudget:20000,plan:null,planner:{people:2,days:5,budget:15000,minutes:45,meal:'dinner',vegetarian:false,exclude:[]},planText:'',checkout:{address:'',slot:'',zone:'almaty',comment:'',replacements:'ask'},busy:false};
function L(ru,kk){return S.language==='kk'?kk:ru;}
function name(p){return S.language==='kk'?(p.name_kk||p.name):p.name;}
function money(n){return new Intl.NumberFormat(S.language==='kk'?'kk-KZ':'ru-RU',{maximumFractionDigits:0}).format(Number(n)||0)+' ₸';}
function date(s){const d=new Date(s);return Number.isNaN(d.getTime())?e(s):d.toLocaleString(S.language==='kk'?'kk-KZ':'ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});}
function uid(){return typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,13);}
function pby(id){return D.products.find(p=>p.id===String(id));}
function pack(p){if(p.unit==='pc')return p.pack+' '+L('шт.','дана');return new Intl.NumberFormat(S.language==='kk'?'kk-KZ':'ru-RU').format(p.pack>=1000?p.pack/1000:p.pack)+' '+(p.unit==='g'?(p.pack>=1000?'кг':'г'):(p.pack>=1000?L('л','л'):L('мл','мл')));}
function amount(v,u){return new Intl.NumberFormat(S.language==='kk'?'kk-KZ':'ru-RU',{maximumFractionDigits:1}).format(v)+' '+(u==='pc'?L('шт.','дана'):u==='g'?'г':'мл');}
function unitPrice(p){return money(Math.round(p.price/p.pack*(p.unit==='pc'?1:1000)))+'/'+(p.unit==='pc'?L('шт.','дана'):p.unit==='g'?'кг':'л');}
