function icon(id,cls=''){return '<svg class="icon '+e(cls)+'" viewBox="0 0 24 24" aria-hidden="true">'+(icons[id]||icons.bag)+'</svg>';}
const emojiByImage={bananas:'🍌',avocado:'🥑',apples:'🍎',oranges:'🍊',bread:'🥖',milk:'🥛',eggs:'🥚',cheese:'🧀',rice:'🍚',pasta:'🍝',chicken:'🍗',tomatoes:'🍅',potatoes:'🥔',carrots:'🥕',onions:'🧅',oil:'🫒',yogurt:'🥣',strawberries:'🍓',coffee:'☕',water:'💧',beef:'🥩',oats:'🥣',butter:'🧈',cucumber:'🥒',salad:'🥗','pasta-dish':'🍝',hero:'🛍️',salt:'🧂',flour:'🌾',lentil:'🫘'};
function photo(image,alt='',emoji='',lazy=true){
 const local=window.KEREK_LOCAL_PHOTOS?.[image],pid=D.photoIds[image];let src=local||(pid?'https://images.unsplash.com/photo-'+pid+'?auto=format&fit=crop&w=500&q=78':image?.startsWith('assets/uploads/')||image?.startsWith('https://images.unsplash.com/')?image:'');
 if(!/^(https:\/\/images\.unsplash\.com\/|assets\/|data:image\/(webp|png|jpeg);base64,)/.test(src))src='';
 return '<span class="photo"><span class="photo-fallback" aria-hidden="true">'+e(emoji||emojiByImage[image]||'🛍️')+'</span>'+(src?'<img src="'+e(src)+'" alt="'+e(alt)+'" '+(lazy?'loading="lazy"':'loading="eager"')+' decoding="async" referrerpolicy="no-referrer">':'<span class="hidden">'+e(alt)+'</span>')+'</span>';
}
function safeArrays(){for(const k of ['favorites','seen','pantry','orders','tickets','addresses','ledger'])if(!Array.isArray(S[k]))S[k]=[];S.cart=C.cleanCart(S.cart,D.products);S.favorites=[...new Set(S.favorites.map(String))].filter(id=>pby(id));S.seen=[...new Set(S.seen.map(String))].filter(id=>pby(id)).slice(0,12);S.pantry=S.pantry.filter(x=>x&&typeof x.ingredient==='string'&&Number.isFinite(Number(x.amount))&&['g','ml','pc'].includes(x.unit));S.addresses=S.addresses.filter(x=>x&&typeof x.text==='string');if(!['ru','kk'].includes(S.language))S.language='ru';if(!['light','dark'].includes(S.theme))S.theme='light';sanitizeHistory();}
function sanitizeHistory(){
 S.name=typeof S.name==='string'?S.name.slice(0,80):'';S.phone=typeof S.phone==='string'?S.phone.slice(0,30):'';
 S.orders=S.orders.filter(o=>o&&typeof o.id==='string'&&Array.isArray(o.items)&&o.quote&&Number.isFinite(Number(o.quote.total))).map(o=>({...o,items:o.items.filter(x=>x&&typeof x.name==='string'&&C.int(x.qty,1,99)),timeline:Array.isArray(o.timeline)?o.timeline.filter(x=>x&&typeof x.status==='string'):[]}));
 S.tickets=S.tickets.filter(x=>x&&typeof x.text==='string'&&typeof x.id==='string');
 S.ledger=S.ledger.filter(x=>x&&Number.isFinite(x.delta));
 S.addresses=S.addresses.slice(0,10).map(x=>({id:String(x.id||uid()).slice(0,100),label:String(x.label||L('Дом','Үй')).slice(0,80),text:x.text.slice(0,300),zone:String(x.zone||'almaty')}));
 S.pantry=S.pantry.filter(x=>x.amount>=0&&x.amount<=1000000).slice(0,150).map(x=>({...x,id:String(x.id||uid()),amount:Number(x.amount),expiresAt:typeof x.expiresAt==='string'?x.expiresAt:'',confirmed:x.confirmed===true}));
 S.balance=Math.max(0,Number(S.balance)||0);S.bonus=Math.max(0,Number(S.bonus)||0);S.promo=typeof S.promo==='string'?S.promo.slice(0,40):'';
}
function migrate(){
 if(load(KEY,null))return;
 const oldCart=load('kerek_basket',{}),oldFav=load('kerek_fav',[]),oldProfile=load('kerek_profile',{}),oldPantry=load('kerek_pantry',[]),oldOrders=load('kerek_orders',[]);
 S.cart=C.cleanCart(oldCart,D.products);S.favorites=Array.isArray(oldFav)?oldFav.map(String).filter(id=>pby(id)):[];
 S.name=typeof oldProfile.name==='string'?oldProfile.name.slice(0,80):'';S.phone=typeof oldProfile.phone==='string'?oldProfile.phone.slice(0,30):'';
 if(Array.isArray(oldPantry))S.pantry=oldPantry.map(id=>pby(id)).filter(Boolean).map(p=>({id:uid(),ingredient:p.ingredient,amount:p.pack,unit:p.unit,expiresAt:'',confirmed:false}));
 if(Array.isArray(oldOrders))S.orders=oldOrders.filter(o=>o&&Array.isArray(o.items)).map(o=>({id:'V2-'+String(o.id).slice(0,30),createdAt:new Date().toISOString(),legacyDate:String(o.date||''),status:'created',address:String(o.address||''),slot:String(o.slot||''),demo:true,legacy:true,items:o.items.map(x=>{let p=D.products.find(p=>p.name.startsWith(String(x.name))||p.name===x.name);return {id:p?.id||'',name:String(x.name),qty:Math.min(99,Math.max(1,Number(x.qty)||1)),price:0};}),quote:{total:Number(o.total)||0,bonus:0,bonusEarned:0},timeline:[]}));
 const oldSupport=load('kerek_support',[]);if(Array.isArray(oldSupport))S.tickets=oldSupport.filter(x=>x&&x.text).map(x=>({id:'V2-'+uid().slice(0,8),text:String(x.text),createdAt:new Date().toISOString(),status:'open',reply:'',demo:true}));
}
function write(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch(_){storageWarning=true;}}
function userState(){return {name:S.name,language:S.language,notifications:S.notifications,addresses:S.addresses.map(a=>({id:a.id,label:a.label,text:a.text,zone:a.zone||'almaty'})),favorites:S.favorites,pantry:S.pantry,cart:S.cart};}
async function sync(){if(!API.enabled||!user)return true;clearTimeout(savingTimer);try{await API.request('me',{method:'PUT',body:userState()});return true;}catch(err){toast(L('Не удалось синхронизировать. Данные остались на этом устройстве.','Синхрондау орындалмады. Деректер осы құрылғыда сақталды.'));return false;}}
function save(remote=true){write();if(remote&&API.enabled&&user){clearTimeout(savingTimer);savingTimer=setTimeout(sync,500);}}
function applyUser(u){user=u;const p=u.state||{};for(const k of ['name','language','notifications','addresses','favorites','pantry','cart'])if(p[k]!==undefined)S[k]=p[k];S.phone=u.phone||'';S.balance=u.balance||0;S.ledger=u.ledger||[];safeArrays();save(false);}
function toast(text,action=null){clearTimeout(toastTimer);const el=$('#toast');el.innerHTML='<span>'+e(text)+'</span>'+(action?'<button data-action="'+e(action.action)+'">'+e(action.label)+'</button>':'');el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),action?7000:4300);}
const errorLabels={auth_required:['Войдите в профиль.','Профильге кіріңіз.'],invalid_credentials:['Неверный логин или пароль.','Логин немесе құпиясөз қате.'],wrong_code:['Неверный код. Проверьте шесть цифр.','Код қате. Алты санды тексеріңіз.'],code_expired:['Код истёк или исчерпаны попытки. Запросите новый.','Код мерзімі өтті немесе әрекеттер таусылды. Жаңасын сұратыңыз.'],too_many_attempts:['Слишком много попыток. Повторите позже.','Әрекеттер тым көп. Кейін қайталаңыз.'],server_unavailable:['Сервер недоступен. Заказ не отправлен.','Сервер қолжетімсіз. Тапсырыс жіберілмеді.'],server_timeout:['Сервер не ответил. Проверьте историю перед повтором.','Сервер жауап бермеді. Қайталамас бұрын тарихты тексеріңіз.'],price_changed:['Цена изменилась. Обновите корзину и подтвердите новую сумму.','Баға өзгерді. Себетті жаңартып, жаңа соманы растаңыз.'],min_order:['Не достигнута минимальная сумма заказа.','Тапсырыстың ең төменгі сомасы жиналмады.'],invalid_slot:['Выберите доступное время доставки.','Жеткізудің қолжетімді уақытын таңдаңыз.'],csrf_rejected:['Сеанс изменился. Выйдите и войдите снова.','Сеанс өзгерді. Шығып, қайта кіріңіз.'],validation_error:['Проверьте заполненные поля.','Толтырылған өрістерді тексеріңіз.'],forbidden:['Недостаточно прав.','Құқықтар жеткіліксіз.'],promo_invalid:['Промокод не найден или истёк.','Промокод табылмады немесе мерзімі өтті.'],promo_min:['Сумма корзины недостаточна для промокода.','Промокод үшін себет сомасы жеткіліксіз.'],empty_cart:['Корзина пуста.','Себет бос.'],cannot_cancel_at_this_stage:['Заказ уже нельзя отменить здесь. Создайте обращение.','Тапсырысты мұнда болдырмау мүмкін емес. Өтініш жасаңыз.'],cancel_active_orders_first:['Сначала отмените активные заказы.','Алдымен белсенді тапсырыстарды болдырмаңыз.'],payment_provider_not_connected:['Платёжный провайдер не подключён.','Төлем провайдері қосылмаған.']};
function errText(err){const key=err?.message||String(err);if(key.startsWith('stock:'))return L('Недостаточно товара на складе. Обновите корзину.','Қоймада өнім жеткіліксіз. Себетті жаңартыңыз.');if(key.startsWith('unknown_product'))return L('Товар больше недоступен. Обновите каталог.','Өнім енді қолжетімсіз. Каталогты жаңартыңыз.');return errorLabels[key]?L(...errorLabels[key]):L('Не удалось выполнить действие. Проверьте данные и подключение.','Әрекет орындалмады. Деректер мен қосылымды тексеріңіз.');}
function q(){return C.quote(S.cart,D.products,D.settings,{promo:S.promo,bonus:S.bonus,balance:user?user.balance:S.balance,zone:V.checkout.zone});}
function cartCount(){return Object.values(S.cart).reduce((s,n)=>s+n,0);}
function btn(action,label,cls='secondary',extra='',ic=''){return '<button class="btn '+e(cls)+'" data-action="'+e(action)+'" '+extra+'>'+(ic?icon(ic):'')+label+'</button>';}
function navButton(view,label,ic,cls=''){return '<button class="'+e(cls)+' '+(V.view===view?'active':'')+'" data-action="nav" data-view="'+view+'">'+icon(ic)+e(label)+'</button>';}
